-- Histórico teórico de sessões, só para a demonstração (dados fictícios).
-- Rode depois de attobrain.sql. Apaga as sessões atuais dos alunos de demonstração e insere o histórico abaixo.
USE attobrain;
DELETE FROM sessoes WHERE aluno_id IN (SELECT id FROM alunos WHERE observacoes LIKE 'Cadastro fictício%');
